#include <iostream>
#include <cassert>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

// Include the header files generated by T007
#include "counter_packed.hpp"
#include "counter_padded.hpp"

// Helper to parse command line arguments
bool parse_args(int argc, char* argv[], std::string& executable_name) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <expected_cache_line_size>" << std::endl;
        return false;
    }
    executable_name = argv[0];
    return true;
}

int main(int argc, char* argv[]) {
    int expected_cache_line_size = 64; // Default assumption
    
    // Attempt to parse expected cache line size from args if provided
    if (argc > 1) {
        try {
            expected_cache_line_size = std::stoi(argv[1]);
        } catch (...) {
            std::cerr << "Warning: Invalid cache line size argument, using default 64" << std::endl;
        }
    }

    std::cout << "Running layout validation for cache line size: " << expected_cache_line_size << " bytes" << std::endl;

    // Test 1: Verify Packed Counter Size
    {
        const size_t packed_size = sizeof(PackedCounter);
        std::cout << "PackedCounter size: " << packed_size << " bytes" << std::endl;
        
        // Based on T007 spec: packed struct should be approx 24 bytes (3 x 8-byte integers)
        // We allow a small tolerance for padding/alignment quirks on specific compilers,
        // but it must be significantly less than a cache line.
        if (packed_size > 32) {
            std::cerr << "FAIL: PackedCounter size (" << packed_size 
                      << ") is unexpectedly large (> 32 bytes). Expected ~24 bytes." << std::endl;
            return 1;
        }
        std::cout << "PASS: PackedCounter size is within expected range." << std::endl;
    }

    // Test 2: Verify Padded Counter Size and Alignment
    {
        const size_t padded_size = sizeof(PaddedCounter);
        std::cout << "PaddedCounter size: " << padded_size << " bytes" << std::endl;
        
        // Based on T007 spec: padded struct should be >= 192 bytes (3 x 64 bytes)
        // This ensures each counter occupies its own cache line (or at least doesn't share).
        // If we have 3 counters, total size should be at least 3 * 64 = 192.
        if (padded_size < 192) {
            std::cerr << "FAIL: PaddedCounter size (" << padded_size 
                      << ") is too small (< 192 bytes). Expected >= 192 bytes." << std::endl;
            return 1;
        }
        
        // Verify alignment is a multiple of 64
        if (padded_size % 64 != 0) {
            std::cerr << "FAIL: PaddedCounter size (" << padded_size 
                      << ") is not a multiple of 64 bytes." << std::endl;
            return 1;
        }
        
        std::cout << "PASS: PaddedCounter size is correct and aligned to 64 bytes." << std::endl;
    }

    // Test 3: Verify Array Alignment for 3 Padded Counters
    {
        struct TestArray {
            PaddedCounter c[3];
        };
        const size_t array_size = sizeof(TestArray);
        std::cout << "Array of 3 PaddedCounters size: " << array_size << " bytes" << std::endl;
        
        // Total size should be exactly 3 * size of PaddedCounter
        const size_t expected_array_size = 3 * sizeof(PaddedCounter);
        if (array_size != expected_array_size) {
            std::cerr << "FAIL: Array size mismatch. Expected " << expected_array_size 
                      << ", got " << array_size << std::endl;
            return 1;
        }
        
        // Verify that the second element starts at an offset >= 64 bytes from the first
        // We can't easily check address offsets in a static test, but we can check the struct
        // size property which implies the offset if alignment is correct.
        // If sizeof(PaddedCounter) >= 64, then the offset between elements is >= 64.
        if (sizeof(PaddedCounter) < 64) {
            std::cerr << "FAIL: PaddedCounter size (" << sizeof(PaddedCounter) 
                      << ") is less than 64 bytes. Elements will share cache lines." << std::endl;
            return 1;
        }
        
        std::cout << "PASS: Array layout ensures cache line separation." << std::endl;
    }

    // Test 4: Verify Packed Array Behavior (False Sharing Potential)
    {
        struct TestPackedArray {
            PackedCounter c[3];
        };
        const size_t packed_array_size = sizeof(TestPackedArray);
        std::cout << "Array of 3 PackedCounters size: " << packed_array_size << " bytes" << std::endl;
        
        // Since packed size is ~24 bytes, 3 of them fit in 72 bytes, which is slightly more than 1 cache line (64)
        // but less than 2 cache lines (128). This confirms they are likely to share cache lines.
        // We just verify the math holds: 3 * ~24 < 128
        if (packed_array_size >= 128) {
            std::cerr << "FAIL: PackedArray size (" << packed_array_size 
                      << ") is unexpectedly large. False sharing simulation might be invalid." << std::endl;
            return 1;
        }
        
        std::cout << "PASS: PackedArray confirms potential for false sharing (size < 128 bytes)." << std::endl;
    }

    std::cout << "All layout validations passed successfully." << std::endl;
    return 0;
}